-- Đặt lại bộ đếm khóa tự tăng theo dữ liệu đã nạp
SELECT setval(pg_get_serial_sequence('auth."AspNetRoleClaims"', 'Id'), COALESCE((SELECT MAX("Id") FROM auth."AspNetRoleClaims"), 1), (SELECT MAX("Id") FROM auth."AspNetRoleClaims") IS NOT NULL);
SELECT setval(pg_get_serial_sequence('auth."AspNetUserClaims"', 'Id'), COALESCE((SELECT MAX("Id") FROM auth."AspNetUserClaims"), 1), (SELECT MAX("Id") FROM auth."AspNetUserClaims") IS NOT NULL);
