INSERT INTO public."Subskill" ("Subskill_ID", "KnowledgeArea_ID", "SubskillCode", "SubskillName", "Description", "SortOrder", "Status") OVERRIDING SYSTEM VALUE VALUES
('66', '35', 'G9-U11-GRA-01', 'Suggest + V-ing', 'Sử dụng suggest/recommend + V-ing để đưa ra lời khuyên.', '1', 'Active'),
('67', '35', 'G9-U11-GRA-02', 'Advice with Should', 'Sử dụng mệnh đề (that) + subject + should + V sau suggest/advise/recommend.', '2', 'Active'),
('68', '36', 'G9-U12-VOC-01', 'Career Choices Vocabulary', 'Từ vựng về nghề nghiệp, tuyển dụng và định hướng việc làm.', '1', 'Active'),
('69', '37', 'G9-U12-GRA-01', 'Concession Clauses', 'Dùng although/though/even though để nối hai ý tương phản.', '1', 'Active'),
('70', '37', 'G9-U12-GRA-02', 'Reason Clauses', 'Dùng because/since/as để giải thích nguyên nhân với mệnh đề đầy đủ.', '2', 'Active'),
('71', '37', 'G9-U12-GRA-03', 'Result Clauses', 'Dùng so...that/such...that và so để diễn đạt kết quả.', '3', 'Active'),
('27', '14', 'G9-U01-VOC-01', 'Local Community Vocabulary', 'Nhận biết và sử dụng từ vựng về cộng đồng địa phương, nghề thủ công và sản phẩm truyền thống.', '1', 'Active'),
('28', '15', 'G9-U01-GRA-01', 'Wh-word Selection', 'Chọn từ để hỏi đúng theo ý nghĩa ngữ cảnh trước cấu trúc to-infinitive.', '1', 'Active'),
('29', '15', 'G9-U01-GRA-02', 'Wh + To-infinitive', 'Nhận diện và tạo cấu trúc question word + to + V nguyên mẫu.', '2', 'Active'),
('30', '15', 'G9-U01-GRA-03', 'Phrasal Verbs 1', 'Chọn cụm động từ có nghĩa phù hợp trong ngữ cảnh cộng đồng và nghề thủ công.', '3', 'Active'),
('31', '16', 'G9-U02-VOC-01', 'City Life Vocabulary', 'Sử dụng từ vựng về giao thông, hạ tầng và cuộc sống đô thị.', '1', 'Active'),
('32', '17', 'G9-U02-GRA-01', 'Comparative Forms', 'Chọn dạng so sánh hơn phù hợp của tính từ và trạng từ.', '1', 'Active'),
('33', '17', 'G9-U02-GRA-02', 'Double Comparatives', 'Sử dụng cấu trúc the + comparative, the + comparative diễn đạt quan hệ đồng biến/nghịch biến.', '2', 'Active'),
('34', '17', 'G9-U02-GRA-03', 'Phrasal Verbs 2', 'Chọn cụm động từ phù hợp các tình huống sinh hoạt tại thành phố.', '3', 'Active'),
('35', '18', 'G9-U03-VOC-01', 'Healthy Living Vocabulary', 'Từ vựng về sức khỏe, học tập, thời gian và sự cân bằng ở tuổi thiếu niên.', '1', 'Active'),
('36', '19', 'G9-U03-GRA-01', 'First Conditional Form', 'Chia động từ đúng trong mệnh đề if và mệnh đề chính có động từ khuyết thiếu.', '1', 'Active'),
('37', '19', 'G9-U03-GRA-02', 'Modal Meaning in Conditionals', 'Phân biệt lời khuyên, nghĩa vụ, khả năng và sự cho phép trong câu điều kiện loại 1.', '2', 'Active'),
('38', '20', 'G9-U04-VOC-01', 'Remembering the Past Vocabulary', 'Từ vựng về đời sống xưa, truyền thống, di sản và bảo tồn.', '1', 'Active'),
('39', '21', 'G9-U04-GRA-01', 'Past Continuous Form', 'Sử dụng was/were + V-ing trong câu khẳng định, phủ định và nghi vấn.', '1', 'Active'),
('40', '21', 'G9-U04-GRA-02', 'Past Simple vs Continuous', 'Phân biệt hành động đang diễn ra và hành động xen vào trong quá khứ.', '2', 'Active'),
('41', '21', 'G9-U04-GRA-03', 'Wish + Past Simple', 'Diễn đạt mong ước trái với hiện tại bằng wish + quá khứ đơn.', '3', 'Active'),
('42', '21', 'G9-U04-GRA-04', 'Wish with Were/Could', 'Sử dụng were/could để nói về trạng thái giả định và khả năng mong muốn ở hiện tại.', '4', 'Active'),
('43', '22', 'G9-U05-VOC-01', 'Our Experiences Vocabulary', 'Từ vựng về trải nghiệm, cảm xúc và đánh giá trải nghiệm.', '1', 'Active'),
('44', '23', 'G9-U05-GRA-01', 'Present Perfect Form', 'Sử dụng have/has + V3 đúng với chủ ngữ và phân từ quá khứ.', '1', 'Active'),
('45', '23', 'G9-U05-GRA-02', 'Ever and Never', 'Sử dụng ever/never trong hiện tại hoàn thành để diễn đạt kinh nghiệm.', '2', 'Active'),
('46', '23', 'G9-U05-GRA-03', 'For and Since', 'Chọn for/since và mốc thời gian hoặc khoảng thời gian phù hợp trong hiện tại hoàn thành.', '3', 'Active'),
('47', '23', 'G9-U05-GRA-04', 'Perfect vs Past Simple', 'Phân biệt hiện tại hoàn thành và quá khứ đơn theo mốc thời gian/kinh nghiệm.', '4', 'Active'),
('48', '24', 'G9-U06-VOC-01', 'Lifestyle Vocabulary', 'Từ vựng về thay đổi lối sống, gia đình, công nghệ và sinh hoạt xưa – nay.', '1', 'Active'),
('49', '25', 'G9-U06-GRA-01', 'Verb + To-infinitive', 'Chọn to + V nguyên mẫu sau các động từ yêu cầu to-infinitive.', '1', 'Active'),
('50', '25', 'G9-U06-GRA-02', 'Verb + V-ing', 'Chọn V-ing sau các động từ yêu cầu gerund.', '2', 'Active'),
('51', '26', 'G9-U07-VOC-01', 'Natural Wonders Vocabulary', 'Từ vựng về danh thắng, địa hình và tham quan thiên nhiên.', '1', 'Active'),
('52', '27', 'G9-U07-GRA-01', 'Reported Yes/No Questions', 'Đổi câu hỏi Yes/No sang lời nói gián tiếp với if/whether.', '1', 'Active'),
('53', '27', 'G9-U07-GRA-02', 'Reported Question Changes', 'Chuyển thì, đại từ và trật tự từ đúng trong câu hỏi Yes/No gián tiếp.', '2', 'Active'),
('54', '28', 'G9-U08-VOC-01', 'Tourism Vocabulary', 'Từ vựng về du lịch, lịch trình, lưu trú và dịch vụ du lịch.', '1', 'Active'),
('55', '29', 'G9-U08-GRA-01', 'Who / Which / That', 'Chọn đại từ quan hệ phù hợp với danh từ chỉ người hoặc vật.', '1', 'Active'),
('56', '29', 'G9-U08-GRA-02', 'Whose in Relative Clauses', 'Sử dụng whose để chỉ sở hữu trong mệnh đề quan hệ.', '2', 'Active'),
('57', '30', 'G9-U09-VOC-01', 'World Englishes Vocabulary', 'Từ vựng về các biến thể tiếng Anh, phát âm và học ngôn ngữ.', '1', 'Active'),
('58', '31', 'G9-U09-GRA-01', 'Relative Clause Agreement', 'Chọn dạng động từ hòa hợp với danh từ được bổ nghĩa bởi mệnh đề quan hệ xác định.', '1', 'Active'),
('59', '31', 'G9-U09-GRA-02', 'Object Pronoun Omission', 'Nhận diện trường hợp có thể lược bỏ đại từ quan hệ làm tân ngữ trong mệnh đề xác định.', '2', 'Active'),
('60', '31', 'G9-U09-GRA-03', 'Combining Defining Clauses', 'Kết hợp hai câu bằng mệnh đề quan hệ xác định với trật tự từ phù hợp.', '3', 'Active'),
('61', '32', 'G9-U10-VOC-01', 'Planet Earth Vocabulary', 'Từ vựng về hệ sinh thái, sinh vật, môi trường và bảo tồn.', '1', 'Active'),
('62', '33', 'G9-U10-GRA-01', 'Non-defining Commas', 'Sử dụng dấu phẩy để tách mệnh đề quan hệ không xác định.', '1', 'Active'),
('63', '33', 'G9-U10-GRA-02', 'Non-defining Pronouns', 'Chọn who/which/whose trong mệnh đề quan hệ không xác định; không dùng that.', '2', 'Active'),
('64', '33', 'G9-U10-GRA-03', 'Combining Non-defining Clauses', 'Kết hợp câu bằng mệnh đề quan hệ không xác định, đúng dấu phẩy và đại từ.', '3', 'Active'),
('65', '34', 'G9-U11-VOC-01', 'Electronic Devices Vocabulary', 'Từ vựng về thiết bị số, khả năng và thao tác công nghệ.', '1', 'Active');
INSERT INTO public."Question" ("Question_ID", "Subskill_ID", "QuestionCode", "QuestionText", "OptionA", "OptionB", "OptionC", "OptionD", "AnswerKey", "DifficultyLevel", "Explanation", "Status", "UsagePurpose") OVERRIDING SYSTEM VALUE VALUES
('82', '27', 'G9-U01-VOC-01-Q01', 'My uncle makes ceramic bowls by hand. He is a skilled ____.', 'artisan', 'athlete', 'astronaut', 'dentist', 'A', '1', 'Đáp án A: artisan. Dùng theo phạm vi: Nhận biết và sử dụng từ vựng về cộng đồng địa phương, nghề thủ công và sản phẩm truyền thống.', 'Active', 'ForTest'),
('83', '27', 'G9-U01-VOC-01-Q02', 'The village is famous for its beautiful ____, including cups and plates.', 'pottery', 'medicine', 'machinery', 'software', 'A', '1', 'Đáp án A: pottery. Dùng theo phạm vi: Nhận biết và sử dụng từ vựng về cộng đồng địa phương, nghề thủ công và sản phẩm truyền thống.', 'Active', 'ForTest'),
('84', '27', 'G9-U01-VOC-01-Q03', 'At the craft centre, visitors bought baskets in the front shop. Behind it, workers wove new baskets using tools and long benches. That production room is the ____.', 'showroom', 'warehouse', 'workshop', 'gallery', 'C', '2', 'Workshop là nơi trực tiếp sản xuất; showroom/gallery dùng để trưng bày, warehouse để lưu trữ.', 'Active', 'ForTest'),
('85', '27', 'G9-U01-VOC-01-Q04', 'The town wants to ____ its traditional crafts for future generations.', 'destroy', 'pollute', 'replace', 'preserve', 'D', '1', 'Đáp án D: preserve. Dùng theo phạm vi: Nhận biết và sử dụng từ vựng về cộng đồng địa phương, nghề thủ công và sản phẩm truyền thống.', 'Active', 'ForTest'),
('86', '27', 'G9-U01-VOC-01-Q05', 'Unlike factory-made souvenirs, the hand-woven scarves are made only in this village and represent its best-known local ____.', 'itinerary', 'speciality', 'landmark', 'exhibition', 'B', '2', 'Local speciality là sản phẩm đặc trưng của địa phương, không phải lịch trình, địa danh hay cuộc trưng bày.', 'Active', 'ForTest'),
('87', '27', 'G9-U01-VOC-01-Q06', 'The visitors watched a craftsperson shape wet clay on a wheel before firing it in a kiln. What did the craftsperson make?', 'lacquerware', 'embroidery', 'bamboo baskets', 'pottery', 'D', '2', 'Pottery được nặn từ đất sét và nung trong lò; các lựa chọn còn lại dùng vật liệu hoặc kỹ thuật khác.', 'Active', 'ForTest'),
('88', '27', 'G9-U01-VOC-01-Q07', 'A family business still uses traditional methods, but its products are sold online. Which phrase best describes its aim?', 'replace handmade goods with imported products', 'preserve a craft while reaching new customers', 'abandon local traditions to reduce costs', 'close the workshop to protect its designs', 'B', '2', 'Preserve a craft là duy trì nghề truyền thống, đồng thời bán hàng qua mạng giúp mở rộng khách hàng.', 'Active', 'ForTest'),
('89', '27', 'G9-U01-VOC-01-Q08', 'The villagers want to protect a centuries-old weaving tradition. They will train young people, document old techniques and sell the cloth to visitors. Which word best describes the overall effort?', 'urbanisation', 'conservation of wildlife', 'heritage preservation', 'industrial automation', 'C', '2', 'Ba hoạt động đều hướng đến gìn giữ di sản nghề truyền thống (heritage preservation), không phải bảo tồn động vật hay tự động hóa.', 'Active', 'ForTest'),
('90', '28', 'G9-U01-GRA-01-Q01', 'We already know the address, but not ____ to get there by bus.', 'what', 'who', 'whose', 'how', 'D', '1', 'Đáp án D: how. Dùng theo phạm vi: Chọn từ để hỏi đúng theo ý nghĩa ngữ cảnh trước cấu trúc to-infinitive.', 'Active', 'ForTest'),
('91', '28', 'G9-U01-GRA-01-Q02', 'I know the place and the route, but not ____ to leave to avoid traffic.', 'who', 'whose', 'when', 'what', 'C', '1', 'Đáp án C: when. Dùng theo phạm vi: Chọn từ để hỏi đúng theo ý nghĩa ngữ cảnh trước cấu trúc to-infinitive.', 'Active', 'ForTest'),
('92', '28', 'G9-U01-GRA-01-Q03', 'There are three museums; I cannot decide ____ to visit first.', 'whose', 'which one', 'who', 'how often', 'B', '1', 'Đáp án B: which one. Dùng theo phạm vi: Chọn từ để hỏi đúng theo ý nghĩa ngữ cảnh trước cấu trúc to-infinitive.', 'Active', 'ForTest'),
('93', '28', 'G9-U01-GRA-01-Q04', 'The guide knows the artist''s name but not ____ to contact for a workshop booking.', 'when', 'why', 'where', 'whom', 'D', '1', 'Đáp án D: whom. Dùng theo phạm vi: Chọn từ để hỏi đúng theo ý nghĩa ngữ cảnh trước cấu trúc to-infinitive.', 'Active', 'ForTest'),
('94', '28', 'G9-U01-GRA-01-Q05', 'We need instructions about ____ to do with these broken baskets.', 'what', 'when', 'where', 'who', 'A', '1', 'Đáp án A: what. Dùng theo phạm vi: Chọn từ để hỏi đúng theo ý nghĩa ngữ cảnh trước cấu trúc to-infinitive.', 'Active', 'ForTest'),
('95', '28', 'G9-U01-GRA-01-Q06', 'We know the workshop starts at 9 a.m., but the invitation does not say ____ to meet the guide: at the gate or inside the building.', 'where', 'when', 'why', 'whose', 'A', '1', 'Cần chọn nơi gặp hướng dẫn viên giữa hai địa điểm: where to meet.', 'Active', 'ForTest'),
('96', '28', 'G9-U01-GRA-01-Q07', 'The organisers have two buses. They have not decided ____ one to take to the craft village.', 'who', 'which', 'when', 'how', 'B', '1', 'Có hai xe để lựa chọn nên dùng which one to take; không hỏi người, thời gian hay cách thức.', 'Active', 'ForTest'),
('97', '28', 'G9-U01-GRA-01-Q08', 'The guide has a map but still needs two details: the meeting point (the gate or the pier) and the departure time (8 or 9 a.m.). She must decide ____ to meet the group and ____ to leave.', 'when / where', 'which / how', 'where / when', 'whose / why', 'C', '3', 'Hai thông tin chưa biết là địa điểm (where) và thời gian (when); cần chọn đúng cả hai từ hỏi.', 'Active', 'ForTest'),
('98', '29', 'G9-U01-GRA-02-Q01', 'We don''t know ____ the old temple.', 'how to reaching', 'how to reach', 'how reach', 'how reaching', 'B', '1', 'Đáp án B: how to reach. Dùng theo phạm vi: Nhận diện và tạo cấu trúc question word + to + V nguyên mẫu.', 'Active', 'ForTest'),
('99', '29', 'G9-U01-GRA-02-Q02', 'Could you show me ____ this basket?', 'how to weaving', 'how weave', 'how to weave', 'how weaving', 'C', '1', 'Đáp án C: how to weave. Dùng theo phạm vi: Nhận diện và tạo cấu trúc question word + to + V nguyên mẫu.', 'Active', 'ForTest'),
('100', '29', 'G9-U01-GRA-02-Q03', 'They asked ____ the tickets.', 'where to buy', 'where to buying', 'where buy', 'where buying', 'A', '1', 'Đáp án A: where to buy. Dùng theo phạm vi: Nhận diện và tạo cấu trúc question word + to + V nguyên mẫu.', 'Active', 'ForTest'),
