INSERT INTO public."QuestionInTest" ("QuestionInTest_ID", "Question_ID", "Test_ID", "SnSQuestionText", "SnSOptionA", "SnSOptionB", "SnSOptionC", "SnSOptionD", "SnSAnswerKey", "SnSSubskill_ID", "QuestionNumber") OVERRIDING SYSTEM VALUE VALUES
('84', '97', '5', 'The guide has a map but still needs two details: the meeting point (the gate or the pier) and the departure time (8 or 9 a.m.). She must decide ____ to meet the group and ____ to leave.', 'when / where', 'which / how', 'where / when', 'whose / why', 'C', '28', '1'),
('85', '96', '5', 'The organisers have two buses. They have not decided ____ one to take to the craft village.', 'who', 'which', 'when', 'how', 'B', '28', '2'),
('86', '95', '5', 'We know the workshop starts at 9 a.m., but the invitation does not say ____ to meet the guide: at the gate or inside the building.', 'where', 'when', 'why', 'whose', 'A', '28', '3'),
('87', '121', '5', 'A city plans to introduce a congestion charge, improve bus services and build cycle lanes. What is the main purpose of combining these measures?', 'to encourage more private car journeys', 'to reduce dependence on private vehicles', 'to replace every bus with a bicycle', 'to make suburban housing more expensive', 'B', '31', '4'),
('88', '120', '5', 'The new metro line has reduced traffic jams because more people now use ____ rather than private motorbikes.', 'pedestrian zones', 'parking facilities', 'public transport', 'residential streets', 'C', '31', '5'),
('89', '119', '5', 'Every morning thousands of people travel from suburban areas to workplaces in the city centre. This daily journey is called a ____.', 'commute', 'detour', 'transfer', 'tour', 'A', '31', '6'),
('90', '88', '5', 'A family business still uses traditional methods, but its products are sold online. Which phrase best describes its aim?', 'replace handmade goods with imported products', 'preserve a craft while reaching new customers', 'abandon local traditions to reduce costs', 'close the workshop to protect its designs', 'B', '27', '7'),
('91', '118', '5', 'Every weekday, Mai travels from her suburban home to an office in the city centre and returns in the evening. She has to ____ a long distance.', 'commute', 'sightsee', 'relocate', 'transfer', 'A', '31', '8'),
('92', '117', '5', 'Air ____ is a serious problem in large cities.', 'tradition', 'pollution', 'pronunciation', 'promotion', 'B', '31', '9'),
('93', '89', '5', 'The villagers want to protect a centuries-old weaving tradition. They will train young people, document old techniques and sell the cloth to visitors. Which word best describes the overall effort?', 'urbanisation', 'conservation of wildlife', 'heritage preservation', 'industrial automation', 'C', '27', '10'),
('94', '87', '5', 'The visitors watched a craftsperson shape wet clay on a wheel before firing it in a kiln. What did the craftsperson make?', 'lacquerware', 'embroidery', 'bamboo baskets', 'pottery', 'D', '27', '11'),
('95', '86', '5', 'Unlike factory-made souvenirs, the hand-woven scarves are made only in this village and represent its best-known local ____.', 'itinerary', 'speciality', 'landmark', 'exhibition', 'B', '27', '12'),
('96', '85', '5', 'The town wants to ____ its traditional crafts for future generations.', 'destroy', 'pollute', 'replace', 'preserve', 'D', '27', '13'),
('97', '129', '5', 'The journey used to take an hour; it now takes forty minutes. Which description is both grammatically and factually correct?', 'The journey is much longer than it used to be.', 'The journey is twenty minutes shorter than before.', 'The journey is twenty minutes more short than before.', 'The journey is more slowly than it used to be.', 'B', '32', '14'),
('98', '128', '5', 'The city has improved its buses. They now run ____ than before, even during the evening rush hour.', 'more frequently', 'more frequent', 'most frequently', 'the more frequent', 'A', '32', '15'),
('99', '127', '5', 'Although the express train costs a little more, it takes forty minutes instead of ninety. It is significantly ____ the local train.', 'fast than', 'more fast than', 'faster than', 'the fastest than', 'C', '32', '16'),
('100', '126', '5', 'The air here is ____ than in the countryside.', 'more bad', 'worse', 'badder', 'worst', 'B', '32', '17'),
('101', '137', '5', 'The city planted more trees. Streets became cooler, and people spent more time walking outside. Which sentence best expresses the relationship?', 'The more trees the city planted, the cooler the streets became.', 'The most trees the city planted, the coolest the streets became.', 'The more trees the city planted, streets became the coolest.', 'The more trees planted, the streets becoming cooler.', 'A', '33', '18'),
('102', '136', '5', 'The more reliable the buses are, ____ people will choose to drive to work.', 'the fewest', 'fewer', 'the less', 'the fewer', 'D', '33', '19'),
('103', '135', '5', 'The ____ the road becomes, the ____ the traffic moves.', 'more narrow / slowest', 'narrowest / slower', 'narrower / more slowly', 'narrower / most slowly', 'C', '33', '20'),
('108', '441', '6', 'The training was ____ useful that everyone took notes, and it was ____ an unusual opportunity that they told their friends about it.', 'such / so', 'too / so', 'so / such', 'so / very', 'C', '71', '1'),
('109', '440', '6', 'The company received ____ a large number of applications that it extended the screening period.', 'so', 'too', 'such', 'enough', 'C', '71', '2'),
('110', '437', '6', 'He was late, ____ he missed the first question.', 'because', 'so', 'despite', 'although', 'B', '71', '3'),
('111', '439', '6', 'The online application form was ____ complicated that several applicants asked for help.', 'such', 'too', 'enough', 'so', 'D', '71', '4'),
('152', '119', '7', 'Every morning thousands of people travel from suburban areas to workplaces in the city centre. This daily journey is called a ____.', 'commute', 'detour', 'transfer', 'tour', 'A', '31', '1'),
