('165', '125', '7', 'My sister drives ____ than I do.', 'more carefully', 'more careful', 'most carefully', 'carefuler', 'A', '32', '14'),
('166', '124', '7', 'Public transport is becoming ____ in this city.', 'most convenient', 'conveniently', 'convenientest', 'more convenient', 'D', '32', '15'),
