('168', '122', '7', 'This bus is ____ than the old one.', 'fastest', 'more fast', 'most fast', 'faster', 'D', '32', '17'),
('169', '134', '7', 'The more carefully you plan, ____ your trip becomes.', 'easiest', 'the easiest', 'easier', 'the easier', 'D', '33', '18'),
('170', '133', '7', 'The higher the rent is, ____ it is for students to live downtown.', 'the harder', 'harder', 'hardest', 'the hardest', 'A', '33', '19'),
('171', '132', '7', 'The more people recycle, ____ waste the city produces.', 'less', 'the less', 'the least', 'least', 'B', '33', '20');
